sys_ui_action.client_script_v2:
function onClick(g_form) {
    openAnnotatePage();
}

function openAnnotatePage() {
    var datasetId = g_form.getValue('datasetid');
    //alert(datasetId);
    var imageid = g_form.getValue('imageid');
    //alert(imageid);
    var url = 'https://app.supervisely.com/app/images2/?datasetId=' + datasetId + '&imageId=' + imageid;
    g_navigation.open(url, "_blank");
    // g_modal.showFrame({
    //     url: 'https://app.supervisely.com/app/images2/?datasetId=' + datasetId + '&imageId=' + imageid,
    //     title: 'Annotate Image',
    //     size: 'fw'
    // });
    g_form.save();

}

